describe('a minimal run', () => {
  it.each(['DECIDER_HTTP_ERROR', 'DECIDER_private-marker'])(
    'guards raw coded exceptions at the manager boundary (%s)',
    async (code) => {
      const engine = await createTestEngine();
      // Test the manager's raw-provider guard before dispatch. Script runner rejections after
      // dispatch now have their own conservative SCRIPT_OUTCOME_UNCERTAIN disposition (#321).
      engine.ports.workspace.resolve = () =>
        Promise.reject(
          Object.assign(new Error('private-marker'), { code, name: 'private-marker', status: 400 }),
        );
      const version = engine.publish(
        singleNodeLoop('raw-provider-error', {
          id: 'script',
          kind: 'script',
          label: 'Script',
          config: { command: 'unused', cwd: 'workspace' },
        }),
      );
      const run = await engine.runToIdle(version.loopId);
      expect(run.failure).toMatchObject({
        code: 'INTERNAL_ERROR',
        message: 'Decision provider request failed',
        details: { code: code === 'DECIDER_HTTP_ERROR' ? code : 'DECIDER_ERROR' },
      });
      expect(JSON.stringify([run, engine.events(run.id), engine.ports.logger.lines])).not.toContain(
        'private-marker',
      );
      expect(engine.ports.logger.lines).toContainEqual(
        expect.objectContaining({
          level: 'warn',
          obj: expect.objectContaining({ name: 'Error', status: 400 }),
        }),
      );
    },
  );
  it('runs trigger to exit and records the expected events', async () => {
    const engine = await createTestEngine();
    const version = engine.publish(minimalLoop());

    ...(details !== undefined ? { details } : {}),
  });
}

function providerFailure(
  request: EvaluationRequest,
  error: unknown,
  provenance: EvaluationProvenance,
): never {
  if (isAbortError(error) || request.signal.aborted) throw error;
  const diagnostic = summarizeDeciderError(error);
  request.ports.logger.warn(
    {
      nodeId: request.nodeId,
      kind: request.config.kind,
      name: diagnostic.name,
      code: diagnostic.code,
      status: diagnostic.status,
    },
    'evaluation provider failed',
  );
  if (diagnostic.code === 'DECIDER_INVALID_RESPONSE')
    fail(request, 'EVALUATION_INVALID_RESPONSE', diagnostic.message, false, { provenance });
  const resumable =
    diagnostic.code === 'DECIDER_UNAVAILABLE' ||
    diagnostic.code === 'DECIDER_NOT_AUTHENTICATED' ||
    diagnostic.code === 'DECIDER_RATE_LIMITED' ||
    diagnostic.code === 'DECIDER_UNREACHABLE' ||
    diagnostic.code === 'DECIDER_TIMEOUT' ||
    (diagnostic.status !== undefined && diagnostic.status >= 500);
  fail(
    request,
    diagnostic.code === 'DECIDER_UNAVAILABLE'
      ? 'EVALUATION_UNAVAILABLE'
      : 'EVALUATION_PROVIDER_FAILED',
    diagnostic.message,
    resumable,
    {
      provenance,
      ...(diagnostic.code ? { code: diagnostic.code } : {}),
      ...(diagnostic.status !== undefined ? { status: diagnostic.status } : {}),
    },
  );
}

function validated(
  request: ClassifierEvaluationRequest,
  value: unknown,
  provenance: EvaluationProvenance,
): ClassifierAnswer {
  const parsed = ClassifierAnswerEmissionSchema.safeParse(value);
  if (!parsed.success)
    fail(
      request,
      'EVALUATION_INVALID_RESPONSE',
      'The evaluator returned an invalid primitive answer',
      false,
      { provenance },
    );
  const problem = validatePrimitiveAnswer(request.config.answer, parsed.data);

