6	import type { CodexOptions, ModelReasoningEffort, ThreadOptions } from '@openai/codex-sdk';
7	import { codexEffortName } from './effort-names.js';
8	import { isolationDefaults, layerConfig, overrideRefusal, table } from './isolation.js';
9	
10	/**
11	 * Building the SDK's client and thread options. The thread settings listed below override their
12	 * machine defaults. The Windows sandbox backend (`windows.sandbox`) remains inherited unless
13	 * explicitly configured through an override; it is distinct from the authored `--sandbox`
14	 * permission level. Configured plugins are inherited while other extensions have isolation
15	 * defaults (ADR-0067).
16	 *
17	 * Verified against `@openai/codex-sdk` 0.160.0 (`dist/index.js`, `CodexExec.run`): the per-thread
18	 * options are turned into these CLI arguments, which come after any `config` overrides and so win
19	 * over both them and `config.toml`:
20	 *
21	 * | ThreadOptions          | CLI argument                                       |
22	 * | ---------------------- | -------------------------------------------------- |
23	 * | `model`                | `--model <id>`                                     |
24	 * | `modelReasoningEffort` | `--config model_reasoning_effort="<level>"`        |
25	 * | `sandboxMode`          | `--sandbox read-only|workspace-write|danger-full-access` |
26	 * | `approvalPolicy`       | `--config approval_policy="never|on-request|on-failure|untrusted"` |
27	 * | `networkAccessEnabled` | `--config sandbox_workspace_write.network_access=<bool>` |
28	 * | `webSearchMode`        | `--config web_search="disabled|cached|live"`       |
29	 * | `workingDirectory`     | `--cd <dir>`                                       |
30	 * | `skipGitRepoCheck`     | `--skip-git-repo-check`                            |
31	 *
32	 * The run records the canonical effort; the CLI receives the provider's name for it, which differs
33	 * only for `none` in a family that calls that level `minimal` (`effort-names.ts`). CLI 0.160.0
34	 * passes `model_reasoning_effort` through to the request as `reasoning.effort` without checking
35	 * it; the model catalog limits each model to the efforts it offers
36	 * (docs/06-harness-integration.md).
37	 */
38	
39	export interface ResolvedSettings {
40	  model: string;
41	  effort: Effort;
42	  options: HarnessOptions;
43	  workingDirectory?: string;
44	}
45	
46	export function threadOptions(settings: ResolvedSettings): ThreadOptions {
47	  const { options } = settings;
48	  return {
49	    model: settings.model,
50	    // SDK 0.160.0 types this field without `none`; it writes the value into the CLI argument as
51	    // is, and the CLI forwards it unchanged (verified live for `gpt-6-luna`, #205).
52	    modelReasoningEffort: codexEffortName(settings.model, settings.effort) as ModelReasoningEffort,
53	    sandboxMode: options.sandbox,
54	    approvalPolicy: options.approval,
55	    networkAccessEnabled: options.networkAccess ?? false,
56	    webSearchMode: options.webSearch ? 'live' : 'disabled',
57	    skipGitRepoCheck: true,
58	    ...(settings.workingDirectory ? { workingDirectory: settings.workingDirectory } : {}),
59	  };
60	}
61	
62	type ConfigValue = NonNullable<CodexOptions['config']>[string];
63	
64	/**
65	 * Keep only values the SDK can serialise to TOML (strings, finite numbers, booleans, arrays and
66	 * objects of those). `null`, `undefined`, and anything else are dropped rather than letting the SDK
67	 * throw at spawn time.
68	 */
69	export function sanitizeConfig(value: unknown): ConfigValue | undefined {
70	  if (typeof value === 'string' || typeof value === 'boolean') return value;
71	  if (typeof value === 'number') return Number.isFinite(value) ? value : undefined;
72	  if (Array.isArray(value)) {
73	    return value.map(sanitizeConfig).filter((v): v is ConfigValue => v !== undefined);
74	  }
75	  if (value && typeof value === 'object') {
76	    // Authored keys such as `__proto__` stay own keys (QA423-01).
77	    const out = table();
78	    for (const [key, child] of Object.entries(value)) {
79	      const clean = sanitizeConfig(child);
80	      if (key && clean !== undefined) out[key] = clean;
81	    }
82	    return out;
83	  }
84	  return undefined;
85	}
86	
87	/**
88	 * Client options: the SDK's `config` (dotted `--config` keys) is the isolation defaults of
89	 * ADR-0063/ADR-0067 with `harnessOptions.configOverrides` layered over them, so a node can opt
90	 * out of inherited plugins or turn another extension back on. The thread options are emitted
91	 * after them, so the corresponding thread settings win over same-key overrides. This precedence
92	 * does not establish the enforcement effect of other sandbox-related keys.
93	 */
94	export function clientOptions(
95	  options: HarnessOptions,
96	  codexBinary: string | undefined,
97	  env: Record<string, string> | undefined,
98	): CodexOptions {
99	  // A key the loop cannot pass as plain `--config` segments refuses the turn (review round 1).
100	  const unplain = invalidCodexConfigKeyPath(options.configOverrides);
101	  if (unplain !== undefined) throw overrideRefusal(unplain.join('.'));
102	  const overrides = sanitizeConfig(options.configOverrides ?? {}) as NonNullable<
103	    CodexOptions['config']
104	  >;
105	  return {
106	    ...(codexBinary ? { codexPathOverride: codexBinary } : {}),
107	    ...(env ? { env } : {}),
108	    config: layerConfig(isolationDefaults(), overrides),
109	  };
110	}
