369	export interface TurnOutcome {
370	  finalText: string;
371	  usage: Usage;
372	  items: HarnessItem[];
373	  /** Set when the turn failed (`turn.failed`, or a fatal stream error with no completion). */
374	  failure?: ClassifiedError;
